/bin/bash -lc "python3 - <<'PY'
import ast,hashlib,json,subprocess
from pathlib import Path
runtime=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001'],text=True))
p=json.loads(Path('proposal.json').read_text())

def validate(value,schema,path='"'$'"'):
 kind=schema.get('type')
 type_ok={'object':lambda x:isinstance(x,dict),'array':lambda x:isinstance(x,list),'string':lambda x:isinstance(x,str),'boolean':lambda x:isinstance(x,bool)}
 if kind in type_ok: assert type_ok[kind](value),(path,kind)
 if 'const' in schema: assert value==schema['const'],path
 if 'enum' in schema: assert value in schema['enum'],path
 if isinstance(value,str) and 'minLength' in schema: assert len(value)>=schema['minLength'],path
 if isinstance(value,list):
  assert len(value)>=schema.get('minItems',0),path
  for i,item in enumerate(value): validate(item,schema.get('items',{}),path+'['+str(i)+']')
 if isinstance(value,dict):
  assert set(schema.get('required',[]))<=set(value),(path,'missing required')
  props=schema.get('properties',{})
  if schema.get('additionalProperties') is False: assert set(value)<=set(props),(path,'unknown keys')
  for key,item in value.items():
   if key in props: validate(item,props[key],path+'.'+key)
validate(p['study'],runtime['study_schema'])
assert runtime['phase']=='propose' and runtime['expected_files']==['proposal.json']
assert p['study']['protocol_ref']==runtime['required_study_protocol_ref']
allowed=set(runtime['context']['allowed_observation_ids'])
assert set(p['study']['evidence_refs'])<=allowed
assert p['parent_trial'] in allowed
assert runtime['context']['previous_runtime_error'] is None
assert 1<=len(p['variants'])<=4 and any(v['role']=='candidate' for v in p['variants'])
assert len({v['file'] for v in p['variants']})==len(p['variants'])
for v in p['variants']:
 assert set(v)=={'name','file','role','config','note'}
 assert v['role'] in {'candidate','control'}
 assert Path(v['file']).name==v['file'] and v['file'].endswith('.py')
 assert isinstance(v['config'],dict)
 assert Path(v['file']).is_file()
retrieved=runtime['context']['latest_knowledge_usage']['retrieved_ids']
assert set(retrieved)=={a['knowledge_id'] for a in p['knowledge_assessments']}
for a in p['knowledge_assessments']:
 assert a['decision'] in {'used','considered','rejected','unresolved'}
 assert set(a)=={'knowledge_id','decision','rationale','transformed_mechanism','variant_names','nearest_work_difference','falsifier'}
 assert not a['variant_names'] # considered, no new adoption claimed
# Count exact diagnostic keys by expanding simple source loops, without Torch.
t=ast.parse(Path('candidate.py').read_text())
d=next(n for n in ast.walk(t) if isinstance(n,ast.FunctionDef) and n.name=='diagnostics')
keys=[]
for node in ast.walk(d):
 if isinstance(node,ast.Dict):
  keys.extend(k.value for k in node.keys if isinstance(k,ast.Constant) and isinstance(k.value,str))
for prefix in ('neither','category_only','brand_only','both'):
 keys.extend(prefix+s for s in ('_count_mean','_present_fraction','_pool_rms'))
keys.extend('selected_'+n+'_mean' for n in ('activity','category','brand','joint'))
for i in range(4): keys.extend(['hist_age_bin_'+str(i)+'_event_fraction','hist_action_'+str(i+1)+'_event_fraction'])
assert len(keys)==63 and len(set(keys))==63
assert len(keys)<=64
for v in p['variants']:
 digest=hashlib.sha256(Path(v['file']).read_bytes()).hexdigest()
 v['note']=v['note'].replace('Local syntax/schema/source/algebra checks planned; Torch unavailable and host execution pending.','Local checks passed: Python syntax, exact literal CONFIG, balanced 2x2, identical Model AST/allocation order, numeric imports/no I/O, ancestor pooling/count methods unchanged, runtime study-schema/protocol/allowed-evidence checks, all five retrieved industry cards assessed, and 63 unique diagnostic keys. Independent pure-Python algebra verified 4096 two-event raw tables, exact margins/totals, singleton/empty cases, the information-collision pair, fixed age boundaries and gap-safe rank cardinalities. These do not execute the Torch module. Torch forward/backward/diagnostics, training and scoring remain host-pending. Source SHA256='+digest+'.')
Path('proposal.json').write_text(json.dumps(p,ensure_ascii=False,indent=2)+'\\n')
validate(p['study'],runtime['study_schema'])
print('PASS: prospective study schema, frozen protocol, authorized observations, parent, four executable module declarations, five knowledge assessments, no prior runtime error, 63 unique diagnostics, source hashes recorded.')
print('Estimated added weights:',64*p['variants'][0]['config']['hidden'][0],'; expected parameters per new variant:',17136931+64*p['variants'][0]['config']['hidden'][0])
print('Available ledger seconds reported by runtime:',runtime['context']['remaining_seconds'])
print('Proposal SHA256:',hashlib.sha256(Path('proposal.json').read_bytes()).hexdigest())
print('No training, installation, test assessment, human-source edits, or runtime-contract edits performed.')
PY"

